contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmt, uint minSum, uint collectAmt) public payable {
        // Ensure we have enough ether to forward.
        require(address(this).balance >= depositAmt);

        // Set up: initialize and set min sum.
        c.SetMinSum(minSum);
        c.Initialized();

        // Record before values.
        uint balBefore = c.balances(address(this));
        uint cBalanceBefore = address(c).balance;

        // Deposit.
        c.Deposit{value: depositAmt}();

        // Attempt to collect.
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values.
        uint balAfter = c.balances(address(this));
        uint cBalanceAfter = address(c).balance;

        // General rule: If collect succeeded and reduced the caller's balance by collectAmt,
        // then the ether held by c also decreased by exactly collectAmt.
        assert(reverted || balAfter != balBefore - collectAmt || cBalanceAfter == cBalanceBefore - collectAmt);
    }

    receive() external payable {}
}

